classdef SplitterDialog < handle
%SPLITTERDIALOG Edit arbitrary Splitter outlets and their fractions.
% =========================================================================
% Javier Berenguer Sabater
% Created: October 2, 2026. Last update: October 14, 2026
% =========================================================================
    properties (SetAccess=private)
        BlockPath;Figure;NameField;FractionTable;ConnectionTable;StatusLabel;DataModel
    end
    properties (Access=private)
        SpecifiedFractions = nan(1,0)
    end
    methods
        function obj=SplitterDialog(blockPath,varargin),p=inputParser;addParameter(p,'Visible','on');parse(p,varargin{:});obj.BlockPath=getfullname(blockPath);if string(get_param(obj.BlockPath,'System'))~="nirp.blocks.Splitter",error('nirp:flowsheet:invalidBlock','SplitterDialog requires a Splitter block.');end;obj.build(char(string(p.Results.Visible)));nirp.flowsheet.internal.formatNumericControls(obj.Figure);obj.load();end
        function delete(obj),if ~isempty(obj.Figure)&&isvalid(obj.Figure),delete(obj.Figure);end,end
        function addOutlet(obj,fraction),if nargin<2,fraction=NaN;end;if size(obj.FractionTable.Data,1)>=20,error('nirp:flowsheet:portLimit','At most 20 outlets are supported.');end;d=obj.FractionTable.Data;d(end+1,:)={sprintf('<missing>'),fraction,[]};obj.FractionTable.Data=d;obj.SpecifiedFractions(end+1)=fraction;origin=obj.DataModel.Fractions.origin;origin(end+1)="empty";if isfinite(fraction),origin(end)="specified";end;obj.closeFractions(origin);end
        function removeOutlet(obj),d=obj.FractionTable.Data;if size(d,1)<=2,error('nirp:flowsheet:invalidPorts','A Splitter requires at least two outlets.');end;d(end,:)=[];obj.FractionTable.Data=d;obj.SpecifiedFractions(end)=[];origin=obj.DataModel.Fractions.origin;origin(end)=[];obj.closeFractions(origin);end
        function setFractions(obj,fractions),fractions=fractions(:);if numel(fractions)<2||numel(fractions)>20,error('nirp:flowsheet:invalidPorts','A Splitter requires 2 to 20 outlets.');end;d=cell(numel(fractions),3);old=obj.FractionTable.Data;for i=1:numel(fractions),if i<=size(old,1),d{i,1}=old{i,1};else,d{i,1}='<missing>';end;if isfinite(fractions(i)),d{i,2}=fractions(i);else,d{i,2}=[];end;d{i,3}=[];end;obj.FractionTable.Data=d;obj.SpecifiedFractions=reshape(fractions,1,[]);origin=repmat("empty",1,numel(fractions));origin(isfinite(fractions))="specified";obj.closeFractions(origin);end
        function values=getValues(obj),values=obj.DataModel;end
        function applied=apply(obj),obj.closeFractions(obj.DataModel.Fractions.origin);applied=false;if strcmp(obj.DataModel.Result.status,'conflict'),obj.alertConflict();return,end;fractions=obj.DataModel.Fractions.value;specs=struct();for i=find(obj.DataModel.Fractions.origin=="specified"),name=sprintf('f%d',i);specs.(name)=struct('si',obj.SpecifiedFractions(i),'unit','1');end;try,set_param(obj.BlockPath,'Fractions',mat2str(fractions,17));writeProducerSpecs(obj.BlockPath,specs);set_param(bdroot(obj.BlockPath),'SimulationCommand','update');obj.refreshConnections();nirp.flowsheet.afterApply(bdroot(obj.BlockPath),obj.StatusLabel);applied=true;catch exception,obj.StatusLabel.Text=exception.message;obj.alertConflict();end,end
        function accept(obj),if obj.apply(),delete(obj);end,end
        function cancel(obj),delete(obj);end
    end
    methods (Static),function dialog=open(blockPath),dialog=nirp.flowsheet.SplitterDialog(blockPath);end,end
    methods (Access=private)
        function build(obj,visible),obj.Figure=uifigure('Name','Splitter','Tag','NirpSplitterDialog','Visible',visible,'Position',[130 90 720 520],'WindowStyle','alwaysontop');main=uigridlayout(obj.Figure,[4 1],'RowHeight',{38,'1x',50,38},'Padding',[12 10 12 10]);h=uigridlayout(main,[1 3],'ColumnWidth',{60,'1x',160});uilabel(h,'Text','Name','HorizontalAlignment','right');obj.NameField=uieditfield(h,'text','Editable','off');uibutton(h,'Text','Unit conversion helper','ButtonPushedFcn',@(~,~) UnitConverterHelper.launch());tabs=uitabgroup(main);split=uitab(tabs,'Title','Split fractions');connections=uitab(tabs,'Title','Connections');g=uigridlayout(split,[3 3],'RowHeight',{24,'1x',32},'ColumnWidth',{90,90,'1x'});tip=uilabel(g,'Text','Specify N-1 fractions; the remaining row is calculated.','FontAngle','italic');tip.Layout.Row=1;tip.Layout.Column=[1 3];obj.FractionTable=uitable(g,'ColumnName',{'Outlet stream','Fraction','Molar flow (mol/s)'},'ColumnEditable',[false true false],'CellEditCallback',@(~,event) obj.fractionEdited(event));obj.FractionTable.Layout.Row=2;obj.FractionTable.Layout.Column=[1 3];add=uibutton(g,'Text','Add outlet','ButtonPushedFcn',@(~,~) obj.addOutlet());add.Layout.Row=3;add.Layout.Column=1;remove=uibutton(g,'Text','Remove','ButtonPushedFcn',@(~,~) obj.removeOutlet());remove.Layout.Row=3;remove.Layout.Column=2;cg=uigridlayout(connections,[2 1],'RowHeight',{30,'1x'});uilabel(cg,'Text','Connected material streams (read only)','FontWeight','bold');obj.ConnectionTable=uitable(cg,'ColumnName',{'Direction','Port','Stream'},'ColumnEditable',[false false false]);obj.StatusLabel=uilabel(main,'Text','Ready.','FontAngle','italic','WordWrap','on');b=uigridlayout(main,[1 5],'ColumnWidth',{'1x',70,90,90,90});uilabel(b,'Text','');uibutton(b,'Text','Help','ButtonPushedFcn',@(~,~) openNirpGuide('guides/flowsheet-units.html#splitter'));uibutton(b,'Text','OK','ButtonPushedFcn',@(~,~) obj.accept());uibutton(b,'Text','Cancel','ButtonPushedFcn',@(~,~) obj.cancel());uibutton(b,'Text','Apply','ButtonPushedFcn',@(~,~) obj.apply());end
        function load(obj),obj.NameField.Value=get_param(obj.BlockPath,'Name');fractions=str2num(get_param(obj.BlockPath,'Fractions'));if isempty(fractions),fractions=[NaN NaN];end;obj.SpecifiedFractions=nan(1,numel(fractions));specText=get_param(obj.BlockPath,'Specifications');d=cell(numel(fractions),3);for i=1:numel(fractions),d{i,1}='<missing>';d{i,2}=fractions(i);d{i,3}=[];end;obj.FractionTable.Data=d;if isempty(strtrim(specText)),origin=repmat("empty",1,numel(fractions));origin(isfinite(fractions))="specified";obj.SpecifiedFractions(origin=="specified")=fractions(origin=="specified");if all(isfinite(fractions))&&numel(fractions)>1,origin(end)="empty";obj.SpecifiedFractions(end)=NaN;d{end,2}=[];obj.FractionTable.Data=d;end;else,specs=nirp.dof.readSpecs(specText);origin=repmat("empty",1,numel(fractions));for i=1:numel(fractions),name=sprintf('f%d',i);if isfield(specs,name),origin(i)="specified";obj.SpecifiedFractions(i)=specs.(name).si;d{i,2}=specs.(name).si;else,d{i,2}=[];end;end;obj.FractionTable.Data=d;end;obj.closeFractions(origin);obj.refreshConnections();end %#ok<ST2NM>
        function refreshConnections(obj),graph=nirp.flowsheet.topology(bdroot(obj.BlockPath));key=matlab.lang.makeValidName(get_param(obj.BlockPath,'Name'));data=cell(0,3);namesOut=strings(0,1);if isfield(graph.Units,key),x=graph.Units.(key);for i=1:numel(x.Inputs),data(end+1,:)={'Input',i,label(x.Inputs{i})};end;for i=1:numel(x.Outputs),name=label(x.Outputs{i});data(end+1,:)={'Output',i,name};namesOut(i)=string(name);end;end;obj.ConnectionTable.Data=data;table=obj.FractionTable.Data;for i=1:size(table,1),if i<=numel(namesOut),table{i,1}=char(namesOut(i));else,table{i,1}='<missing>';end;end;obj.FractionTable.Data=table;end
        function fractionEdited(obj,event),origin=obj.DataModel.Fractions.origin;row=event.Indices(1);if (isstruct(event)&&isfield(event,'NewData'))||(~isstruct(event)&&isprop(event,'NewData')),value=event.NewData;else,value=obj.FractionTable.Data{row,2};end;if ischar(value)||isstring(value),value=str2double(value);end;if isempty(value)||(isnumeric(value)&&isscalar(value)&&isnan(value)),origin(row)="empty";obj.SpecifiedFractions(row)=NaN;else,origin(row)="specified";obj.SpecifiedFractions(row)=value;end;obj.closeFractions(origin);end
        function valid=closeFractions(obj,origin)
            values=obj.readFractions();n=numel(values);if numel(origin)~=n,origin=repmat("empty",1,n);end
            if numel(obj.SpecifiedFractions)~=n,obj.SpecifiedFractions=nan(1,n);end
            specs=struct();for i=1:n,if origin(i)=="specified",if ~isfinite(obj.SpecifiedFractions(i))&&isfinite(values(i)),obj.SpecifiedFractions(i)=values(i);end;if isfinite(obj.SpecifiedFractions(i)),name=sprintf('f%d',i);specs.(name)=struct('si',obj.SpecifiedFractions(i),'unit','1');end;else,obj.SpecifiedFractions(i)=NaN;end,end
            try
                state=previewState(obj.BlockPath,n,specs);result=state.Result;
            catch exception
                result=failure(n,exception.message);state=struct('InletSource',"",'Output',struct('sources',struct()));
            end
            newOrigin=repmat("empty",1,n);flows=nan(1,n);
            for i=1:n,name=sprintf('f%d',i);values(i)=result.values.(name);newOrigin(i)=string(result.origins.(name));out=sprintf('F_out%d',i);if isfield(result.values,out),flows(i)=result.values.(out);end,end
            obj.writeFractions(values,flows);obj.DataModel=struct('Fractions',struct('value',values,'unit',"1",'origin',newOrigin),'Outflows',flows,'Result',result);obj.showOrigins(newOrigin,result,state.Output,isempty(state.Inlet));valid=strcmp(result.status,'complete');
            if strcmp(result.status,'conflict'),message='Conflict: '+strjoin(result.messages,' ');elseif strcmp(result.status,'missing'),message=result.messages(end);else,message="Fully specified";if strlength(state.InletSource)>0,message=message+" - "+state.InletSource;end;end;[~,~,runLabel]=nirp.flowsheet.blockStatus(obj.BlockPath);message=message+" - "+runLabel;if isempty(state.Inlet),message=message+"; outlet flows need a run or a defined feed";end
            nirp.flowsheet.internal.paintDofStatus(obj.StatusLabel,result.status,message);
        end
        function values=readFractions(obj),d=obj.FractionTable.Data;values=NaN(1,size(d,1));for i=1:size(d,1),v=d{i,2};if isnumeric(v)&&isscalar(v)&&~isempty(v),values(i)=v;elseif ischar(v)||isstring(v),parsed=str2double(v);if isscalar(parsed),values(i)=parsed;end,end,end,end
        function writeFractions(obj,values,flows),if nargin<3,flows=nan(size(values));end;d=obj.FractionTable.Data;for i=1:numel(values),if isnan(values(i)),d{i,2}=[];else,d{i,2}=nirp.flowsheet.internal.formatTableNumber(values(i));end;if isnan(flows(i)),d{i,3}=[];else,d{i,3}=nirp.flowsheet.internal.formatTableNumber(flows(i));end;end;obj.FractionTable.Data=d;end
        function showOrigins(obj,origin,result,output,waiting),states=origin;states(ismember("f"+string(1:numel(origin)),result.conflicts))="conflict";nirp.flowsheet.internal.styleDofTable(obj.FractionTable,2,states);flowStates=strings(1,numel(origin));for i=1:numel(origin),flowStates(i)=string(result.states.(sprintf('F_out%d',i)));end;if waiting,flowStates(flowStates=="empty")="external";end;nirp.flowsheet.internal.styleDofTable(obj.FractionTable,3,flowStates);sources=fieldnames(output.sources);if waiting,obj.FractionTable.Tooltip='needs a run or a defined feed';elseif isempty(sources),obj.FractionTable.Tooltip='';else,obj.FractionTable.Tooltip=char(strjoin(string(struct2cell(output.sources)),'; '));end,end
        function alertConflict(obj),if isvalid(obj.Figure)&&strcmp(obj.Figure.Visible,'on'),uialert(obj.Figure,obj.StatusLabel.Text,'Splitter','Icon','error');end,end
    end
end
function s=label(v),if isempty(v),s='<missing>';else,s=char(strjoin(string(v),', '));end,end
function result=failure(n,message),values=struct();origins=struct();states=struct();names=strings(0,1);for i=1:n,for prefix={'f','F_out'},name=sprintf('%s%d',prefix{1},i);values.(name)=NaN;origins.(name)='empty';states.(name)='conflict';names(end+1)=string(name);end,end;result=struct('values',values,'origins',origins,'states',states,'messages',string(message),'status','conflict','missingCount',0,'missing',strings(0,1),'conflicts',names);end
function writeProducerSpecs(block,specs),if isempty(fieldnames(specs)),set_param(block,'Specifications','{}');else,nirp.dof.writeSpecs(block,specs);end,end
function state=previewState(block,n,specs)
    stored=str2num(get_param(block,'Fractions')); %#ok<ST2NM>
    if numel(stored)==n,state=nirp.dof.producerState(block,'InternalSpecifications',specs);return,end
    [inlet,source]=nirp.dof.knownInlet(block);output=nirp.dof.connectedSpecifications(block);model=nirp.dof.catalog.splitter(n);
    if isempty(inlet),flow=NaN;else,flow=sum(inlet.F);end
    result=nirp.dof.resolveProducer(model,'Splitter',get_param(block,'Name'),specs,output,struct('F_in',flow),struct('F_in','external'));
    state=struct('Result',result,'Output',output,'Inlet',inlet,'InletSource',source);
end
